# Inventory report script
$ErrorActionPreference = 'Stop'

enum Level {
    Low
    High
}

class Item {
    [string]$Name
    [int]$Count

    Item([string]$name, [int]$count) {
        $this.Name = $name
        $this.Count = $count
    }

    [Level] GetLevel() {
        if ($this.Count -gt 100) {
            return [Level]::High
        }
        return [Level]::Low
    }
}

function Get-Total {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Item[]]$Items
    )
    process {
        $sum = 0
        foreach ($item in $Items) {
            $sum += $item.Count
        }
        $sum
    }
}

$items = @(
    [Item]::new('bolt', 120),
    [Item]::new('nut', 4)
)
$table = @{ Name = 'inventory'; Size = $items.Count }
switch ($items.Count) {
    0 { Write-Warning 'empty' }
    default { Write-Output "count: $($items.Count)" }
}
try {
    Get-Total -Items $items | ForEach-Object { "total=$_" }
}
catch {
    Write-Error $_.Exception.Message
}
finally {
    Write-Verbose 'done'
}

